def semver_sort(versions):
    def parse(v):
        # strip build metadata
        core = v.split('+', 1)[0]
        if '-' in core:
            main_part, pre_part = core.split('-', 1)
        else:
            main_part, pre_part = core, None

        major, minor, patch = (int(x) for x in main_part.split('.'))
        main_tuple = (major, minor, patch)

        if pre_part is None:
            # no prerelease -> sorts after versions with prerelease
            return (main_tuple, 1, ())
        else:
            idents = pre_part.split('.')
            key_idents = []
            for ident in idents:
                if ident.isdigit():
                    key_idents.append((0, int(ident)))
                else:
                    key_idents.append((1, ident))
            return (main_tuple, 0, tuple(key_idents))

    indexed = list(enumerate(versions))
    indexed.sort(key=lambda pair: (parse(pair[1]), pair[0]))
    return [v for _, v in indexed]

